document.querySelectorAll('[data-wa]').forEach(link => {
  link.href = 'https://wa.me/553591558356?text=' + encodeURIComponent(link.dataset.wa);
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
});
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog=[],storeSettings={theme:'light',accent:'orange'};
const section=document.querySelector('#produtos');
const tools=document.createElement('div');tools.className='shop-tools';tools.hidden=true;tools.innerHTML='<input id="shop-search" type="search" aria-label="Buscar produtos" placeholder="Encontre seu próximo produto…"><select id="shop-category" aria-label="Categoria"><option value="">Todas as categorias</option><option>iPhone</option><option>Xiaomi</option><option>PlayStation</option><option>Xbox</option><option>Acessórios</option></select>';
const grid=document.createElement('div');grid.className='live-catalog';grid.hidden=true;section.querySelector('.section-heading').after(tools,grid);
function renderCatalog(){const q=document.querySelector('#shop-search').value.toLocaleLowerCase('pt-BR'),cat=document.querySelector('#shop-category').value;const list=catalog.filter(p=>(!cat||p.category===cat)&&p.name.toLocaleLowerCase('pt-BR').includes(q));grid.innerHTML=list.length?list.map(p=>{const message=p.stock>0?'Olá! Tenho interesse no produto '+p.name+'. Gostaria de saber mais.':'Olá! Gostaria de saber sobre a reposição do produto '+p.name+'.';const href='https://wa.me/553591558356?text='+encodeURIComponent(message);return `<article class="shop-product"><div class="shop-photo">${p.image?`<img src="${escapeHTML(p.image)}" alt="${escapeHTML(p.name)}" loading="lazy" referrerpolicy="no-referrer">`:'<span aria-hidden="true">▦</span>'}${p.featured?'<span class="shop-featured">DESTAQUE</span>':''}</div><div class="shop-details"><p class="shop-meta">${escapeHTML(p.category)} · ${escapeHTML(p.condition)}</p><h3>${escapeHTML(p.name)}</h3><p class="shop-description">${escapeHTML(p.description)}</p><p class="shop-price">${p.price===null?'Sob consulta':(p.price/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</p><p class="shop-stock ${p.stock===0?'out':''}">${p.stock>0?'Disponível em estoque':'Sem estoque no momento'}</p><a class="button orange" href="${href}" target="_blank" rel="noopener noreferrer">${p.stock>0?'Consultar pelo WhatsApp':'Consultar reposição'} ↗</a></div></article>`;}).join(''):'<p class="shop-empty">Nenhum produto encontrado. Tente outra busca.</p>';grid.querySelectorAll('img').forEach(img=>img.onerror=()=>{const span=document.createElement('span');span.textContent='▦';span.setAttribute('aria-label','Foto indisponível');img.replaceWith(span);});}
document.querySelector('#shop-search').oninput=renderCatalog;document.querySelector('#shop-category').onchange=renderCatalog;
const footerControls=document.createElement('div');footerControls.className='footer-admin';footerControls.innerHTML='<a href="/admin" class="store-admin">Área administrativa ↗</a><select class="theme-select" id="visitor-theme" aria-label="Tema da sua visualização"><option value="default">Tema da loja</option><option value="light">Claro</option><option value="dark">Escuro</option><option value="system">Automático</option></select>';document.querySelector('footer').append(footerControls);
try{document.querySelector('#visitor-theme').value=localStorage.getItem('up-visitor-theme')||'default';}catch{}
function updateVisitorTheme(){const mode=document.querySelector('#visitor-theme').value;applyTheme({...storeSettings,theme:mode==='default'?storeSettings.theme:mode});}
document.querySelector('#visitor-theme').onchange=()=>{try{localStorage.setItem('up-visitor-theme',document.querySelector('#visitor-theme').value);}catch{}updateVisitorTheme();};matchMedia('(prefers-color-scheme: dark)').addEventListener('change',updateVisitorTheme);
fetch('/api/catalog').then(async r=>{if(!r.ok)throw new Error();return r.json();}).then(data=>{catalog=data.products;storeSettings=data.settings;updateVisitorTheme();if(catalog.length){section.querySelector('.product-grid').hidden=true;grid.hidden=false;tools.hidden=false;renderCatalog();document.querySelector('.category-strip a[href="#iphones"]').href='#produtos';}}).catch(()=>{const p=document.createElement('p');p.className='catalog-error';p.textContent='O catálogo está temporariamente indisponível. Consulte os produtos pelo WhatsApp.';section.append(p);updateVisitorTheme();});
